"""Event summaries (ES + EN) written by Claude from the transcript, chat and slides.

Division of labour
  * Claude writes the narrative (title, lead, arguments, quotes, Q&A, next session).
  * The participation paragraph is generated by code from the stats, so numbers
    are never invented.
  * After writing, every quotation is checked against the transcript and names
    are checked against slides / chat / participant list. Problems go to review.md.

Without ANTHROPIC_API_KEY the pipeline still runs: it writes `prompt_es.md`
in the event folder, which can be pasted into Claude by hand.
"""
from __future__ import annotations

import json
import os
import re
from pathlib import Path

import yaml
from rapidfuzz import fuzz

from . import normalize as N
from .parsers import ChatMsg, Utterance, is_question

from . import paths
MODEL = os.environ.get("EVENTKIT_MODEL", "claude-opus-5-5")

MONTHS_ES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto",
             "septiembre", "octubre", "noviembre", "diciembre"]
MONTHS_EN = ["January", "February", "March", "April", "May", "June", "July", "August",
             "September", "October", "November", "December"]


def series_config() -> dict:
    p = paths.config_file("series.yml")
    return yaml.safe_load(p.read_text(encoding="utf-8")) if p.exists() else {}


# ------------------------------------------------------------ source prep

def trim_transcript(utts: list[Utterance], meta, margin_min=10) -> list[Utterance]:
    """Drop the pre-show (tech checks) using the gap between webinar opening and planned start."""
    if not utts or meta.planned_start is None or meta.t0 is None:
        return utts
    offset = (meta.planned_start - meta.t0).total_seconds() - margin_min * 60
    kept = [u for u in utts if u.t >= offset]
    return kept or utts


def transcript_text(utts: list[Utterance]) -> str:
    """Merge consecutive lines by the same speaker into paragraphs."""
    out, cur, buf, t0 = [], None, [], 0
    for u in utts:
        if u.speaker != cur:
            if buf:
                out.append(f"[{t0 // 3600}:{t0 % 3600 // 60:02d}] {cur}: {' '.join(buf)}")
            cur, buf, t0 = u.speaker, [], u.t
        buf.append(u.text)
    if buf:
        out.append(f"[{t0 // 3600}:{t0 % 3600 // 60:02d}] {cur}: {' '.join(buf)}")
    return "\n\n".join(out)


def chat_text(chat: list[ChatMsg], staff: set[str]) -> str:
    lines = []
    for m in chat:
        tag = "ORGANIZADOR" if N.norm_text(m.name) in staff else ("PREGUNTA" if is_question(m.text) else "")
        lines.append(f"{m.time:%H:%M} {m.name}{' [' + tag + ']' if tag else ''}: {m.text}"
                     + (f"  (links: {', '.join(m.links)})" if m.links else ""))
    return "\n".join(lines)


def stats_paragraph(s: dict, lang="es") -> str:
    subj_es = "La sesión" if "webinar" in str(s.get("type", "Webinar")).lower() else "El evento"
    subj_en = "The session" if subj_es == "La sesión" else "The event"
    """Participation paragraph from numbers only."""
    n = s["participants_total"]
    d = s["demographics"]
    rounded = (n // 10) * 10
    big = [N.country_meta(c["key"])["en"] if lang == "en" else c["key"]
           for c in d["countries"] if c["pct"] >= 10]
    secs = d["sectors"][:2]
    women = d["women_pct"]
    lac = d["lac_pct"]

    def join(xs, y):
        return xs[0] if len(xs) == 1 else ", ".join(xs[:-1]) + f" {y} " + xs[-1]

    if lang == "es":
        cnt = f"más de {rounded}" if n > rounded else f"{n}"
        p = f"{subj_es} reunió a **{cnt} participantes de {d['countries_n']} países**"
        p += f", de los cuales el {lac:.0f}% provenía de América Latina y el Caribe." if lac is not None else "."
        if big:
            p += (f" {join(big, 'y')} representaron, cada uno, más del 10% de los asistentes." if len(big) > 1
                  else f" {big[0]} representó más del 10% de los asistentes.")
        if women is not None:
            p += f" Las mujeres constituyeron el {women:.0f}% de la participación."
        if len(secs) == 2:
            a, b = (N.sector_label(x["key"], "es_def") for x in secs)
            rest = [N.sector_label(x["key"], "es_def") for x in d["sectors"][2:] if x["key"] != "otros"][:3]
            p += (f" Por sector, destacaron {a} ({secs[0]['pct']:.0f}%) y {b} ({secs[1]['pct']:.0f}%)")
            p += (f"; el resto correspondió a {', '.join(rest)} y otros actores." if rest else ".")
            p = p.replace(" a el ", " al ")
        return p
    cnt = f"more than {rounded}" if n > rounded else f"{n}"
    p = f"{subj_en} brought together **{cnt} participants from {d['countries_n']} countries**"
    p += f", {lac:.0f}% of them from Latin America and the Caribbean." if lac is not None else "."
    if big:
        p += (f" {join(big, 'and')} each accounted for more than 10% of attendees." if len(big) > 1
              else f" {big[0]} accounted for more than 10% of attendees.")
    if women is not None:
        p += f" Women made up {women:.0f}% of participants."
    if len(secs) == 2:
        a, b = (N.sector_label(x["key"], "en_def") for x in secs)
        rest = [N.sector_label(x["key"], "en_def") for x in d["sectors"][2:] if x["key"] != "otros"][:3]
        p += f" By sector, {a} accounted for {secs[0]['pct']:.0f}% and {b} for {secs[1]['pct']:.0f}%"
        p += (f"; the rest came from {', '.join(rest)} and other actors." if rest else ".")
    return p


# -------------------------------------------------------------- prompting

SYSTEM_ES = """Eres periodista de la Unidad de Comunicaciones de la CEPAL. Redactas notas informativas \
para el sitio web sobre eventos que ya ocurrieron (seminarios web, seminarios presenciales, talleres, conferencias). Escribes en español neutro, claro y sobrio, \
en tercera persona y en pasado, con el estilo institucional de Naciones Unidas.

REGLAS DE CONTENIDO
- Usa solo hechos presentes en las fuentes. No inventes cifras, cargos, instituciones ni conclusiones.
- Las diapositivas son la fuente autorizada para nombres, cargos, instituciones y cifras. La transcripción \
automática tiene errores de reconocimiento de voz (nombres y siglas mal escritos): corrígelos con las \
diapositivas, el chat y la lista de panelistas.
- El "resumen automático de Webex" es solo una guía de orientación y contiene errores conocidos \
(p. ej., confunde apellidos con cargos o atribuye preguntas del chat al moderador). Nunca lo uses \
como fuente de un dato que no puedas confirmar en la transcripción, el chat o las diapositivas.
- Las citas textuales deben ser fieles a la transcripción: puedes quitar muletillas ("eh", repeticiones) \
y corregir errores evidentes de transcripción, pero no reformular. Cada cita será verificada \
automáticamente contra la transcripción. Incluye dos citas, máximo tres.
- Ignora la conversación técnica previa y posterior a la sesión (pruebas de audio, logística).
- NO escribas el párrafo de cifras de participación: se añade automáticamente.
- Las preguntas del público se resumen por temas, sin nombrar a las personas del público.

ESTRUCTURA (como en el ejemplo)
1. Título: una frase informativa que sintetice la idea central (sin el nombre del ponente).
2. Bajada: una oración en cursiva que resuma la sesión.
3. Primer párrafo: idea central + nombre de la serie (si el evento pertenece a una), organizadores, fecha, ponente con cargo e institución, moderación.
4. Apertura institucional (si la hubo): quién abrió y qué destacó.
5. Tres a cinco párrafos con los argumentos principales del ponente, con las citas.
6. Un párrafo sobre los temas del diálogo con el público.
7. Próxima sesión (si se anunció): título entre « », fecha, hora, ponente e institución, y una oración \
sobre el tema. Incluye el enlace de inscripción si aparece en el chat.

FORMATO
- Títulos de sesiones y publicaciones entre « »; citas entre “ ”.
- Negritas solo para: cifras del párrafo de participación (no lo escribas), título/fecha/ponente de la próxima sesión.
- Extensión del cuerpo: 400 a 600 palabras.
"""

OUTPUT_SPEC = """Responde SOLO con un objeto JSON válido, sin texto adicional, con esta forma:
{
  "title": "...",
  "lead": "...",
  "body": ["párrafo 1", "párrafo 2", "..."],
  "next_session": "párrafo o null",
  "registration_url": "url o null",
  "speaker": "Nombre Apellido",
  "speaker_affiliation": "Cargo, Institución",
  "event_title": "título de esta sesión si se conoce, o null",
  "uncertain": ["dato que no pudiste confirmar y conviene revisar", "..."]
}
Usa markdown simple dentro de los párrafos (**negrita**, *cursiva*, [texto](url))."""


def build_prompt_es(ctx: dict) -> str:
    from . import catalog as CAT
    exf = CAT.style_example_path((ctx.get("series") or {}).get("id"))
    ex = exf.read_text(encoding="utf-8") if exf.exists() else "(sin ejemplo: sigue la estructura indicada)"
    ser = ctx.get("series") or {}
    overrides = ctx.get("overrides") or {}
    standalone = ser.get("id") == "individuales"
    parts = [
        "## EJEMPLO DE ESTILO (nota publicada de una sesión anterior; imita estructura y tono, no el contenido)\n" + ex,
        "## DATOS DEL EVENTO\n" + yaml.safe_dump({
            **({} if standalone else {"serie": ser.get("name_es")}),
            "tipo_de_evento": ctx.get("event_type"),
            "organizadores": ser.get("organizers_es"),
            "nombre_en_webex": ctx["webinar_name"],
            "fecha": ctx["date_es"],
            "panel_y_organizadores_conectados": ctx["panel"],
            **({"datos_confirmados_por_el_equipo": overrides} if overrides else {}),
        }, allow_unicode=True, sort_keys=False),
        "## DIAPOSITIVAS (fuente autorizada para nombres y cifras)\n" + (ctx["slides"] or "(no disponibles)"),
        "## CHAT DE LA SESIÓN\n" + (ctx["chat"] or "(no disponible)"),
        "## TRANSCRIPCIÓN AUTOMÁTICA (desde poco antes del inicio programado)\n" + ctx["transcript"],
        "## RESUMEN AUTOMÁTICO DE WEBEX (solo orientación; contiene errores)\n" + (ctx["ai_summary"] or "(no disponible)"),
        "## TAREA\nRedacta la nota informativa en español siguiendo las reglas.\n" + OUTPUT_SPEC,
    ]
    return "\n\n".join(parts)


def build_prompt_en(article_es: dict, stats_par_en: str) -> str:
    return (
        "Translate this ECLAC news article from Spanish into English for the ECLAC English website. "
        "Use UN/ECLAC English house style (British spelling as used by the UN, e.g. 'organization', "
        "'programme'; 'Latin America and the Caribbean'; ECLAC instead of CEPAL; UNU-MERIT unchanged). "
        "Translate quotations faithfully into English. Use “ ” for quotes and italics or quotation marks for "
        "session titles. Keep the same structure and markdown. Do not add or remove facts.\n\n"
        f"For reference, the participation paragraph (already written, do NOT include it) reads:\n{stats_par_en}\n\n"
        "ARTICLE (JSON):\n" + json.dumps(article_es, ensure_ascii=False, indent=1) + "\n\n"
        "Reply ONLY with a JSON object with the same keys (title, lead, body, next_session, registration_url, "
        "speaker, speaker_affiliation, event_title, uncertain)."
    )


def _client():
    if not os.environ.get("ANTHROPIC_API_KEY"):
        return None
    import anthropic
    return anthropic.Anthropic()


def _ask(client, system: str | None, prompt: str, max_tokens=6000) -> dict:
    kw = {"system": system} if system else {}
    msg = client.messages.create(model=MODEL, max_tokens=max_tokens,
                                 messages=[{"role": "user", "content": prompt}], **kw)
    text = "".join(b.text for b in msg.content if getattr(b, "type", "") == "text")
    m = re.search(r"\{.*\}", text, re.S)
    return json.loads(m.group(0))


def classify_orgs_with_claude(items: list[dict]) -> dict:
    """items: [{organization, job_title, email_domain}] -> {organization: sector_key}."""
    client = _client()
    if client is None or not items:
        return {}
    keys = list(N.sector_rules()["labels"].keys())
    prompt = ("Clasifica cada organización en uno de estos sectores: " + ", ".join(keys) + ". "
              "publico = gobierno, ministerios, municipios, agencias y empresas estatales; academia = universidades, "
              "centros de investigación, escuelas, estudiantes; internacional = organismos internacionales y de "
              "cooperación; sociedad_civil = ONG, fundaciones, asociaciones civiles; privado = empresas, gremios, "
              "consultoras; otros = independientes, jubilados, texto que no es una organización (direcciones, números). "
              "Usa el cargo y el dominio del correo como pista. Responde SOLO con JSON {\"organización\": \"sector\"}.\n\n"
              + json.dumps(items, ensure_ascii=False))
    try:
        out = _ask(client, None, prompt, max_tokens=8000)
    except Exception as e:  # never block the pipeline on classification
        print(f"[eventkit] sector classification skipped: {e}")
        return {}
    return {k: v for k, v in out.items() if v in keys}


# ------------------------------------------------------------- assembly

def to_markdown(a: dict, stats_par: str, lang="es") -> str:
    out = [f"# {a['title']}", "", f"*{a['lead']}*", ""]
    for p in a["body"]:
        out += [p, ""]
    out += ["<!-- stats:start (auto-generated from the participation data; edits here are overwritten) -->",
            stats_par, "<!-- stats:end -->", ""]
    if a.get("next_session"):
        out += [a["next_session"], ""]
        if a.get("registration_url") and a["registration_url"] not in a["next_session"]:
            out += [("Las personas interesadas pueden inscribirse mediante el "
                     f"[formulario de registro]({a['registration_url']}).") if lang == "es" else
                    f"Registration is available through the [registration form]({a['registration_url']}).", ""]
    return "\n".join(out).strip() + "\n"


def refresh_stats_paragraph(md_path: Path, stats_par: str):
    """Replace the auto-generated participation paragraph in an (edited) summary."""
    if not md_path.exists():
        return
    t = md_path.read_text(encoding="utf-8")
    new = re.sub(r"(<!-- stats:start[^>]*-->\n).*?(\n<!-- stats:end -->)",
                 lambda m: m.group(1) + stats_par + m.group(2), t, flags=re.S)
    if new != t:
        md_path.write_text(new, encoding="utf-8")


QUOTE_RE = re.compile(r"[“«\"]([^”»\"]{25,})[”»\"]")


def review(md_es: str, sources: dict, article: dict) -> str:
    """Quote verification + names to double-check."""
    tr = N.norm_text(sources["transcript_raw"])
    ser = sources.get("series") or {}
    other = N.norm_text(" ".join([sources["slides"], sources["chat"], sources.get("webinar_name", ""),
                                  ser.get("name_es", ""), ser.get("name_en", "")]))
    lines = ["# Revisión automática / Automatic review", ""]
    lines += ["## Citas / Quotes", ""]
    any_q = False
    for q in QUOTE_RE.findall(md_es):
        any_q = True
        nq = N.norm_text(q)
        if nq in other:
            continue  # a title, not a quote
        score = fuzz.partial_ratio(nq, tr)
        mark = "✅" if score >= 85 else ("⚠️" if score >= 70 else "❌")
        lines.append(f"- {mark} {score:.0f}% — “{q[:160]}”")
    if not any_q:
        lines.append("- (sin citas)")
    lines += ["", "## Nombres a verificar / Names to verify", ""]
    known = N.norm_text(" ".join([sources["slides"], sources["chat"], sources["panel_names"], sources["transcript_raw"]]))
    names = set(re.findall(r"\b([A-ZÁÉÍÓÚÑ][a-záéíóúñ]+(?: (?:de |del |la )?[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+)+)\b", md_es))
    missing = sorted(n for n in names if N.norm_text(n) not in known)
    lines += [f"- {n} (no aparece literalmente en las fuentes)" for n in missing] or ["- (ninguno)"]
    if article.get("uncertain"):
        lines += ["", "## Dudas señaladas por Claude / Flagged by Claude", ""]
        lines += [f"- {u}" for u in article["uncertain"]]
    return "\n".join(lines) + "\n"


def make_context(meta, utts, chat, slides, ai_summary, people, overrides, series=None, event_type="Webinar") -> dict:
    staff = people[people.role != "attendee"]
    staff_names = {N.norm_text(x) for x in staff.display_name.dropna()}
    trimmed = trim_transcript(utts, meta)
    d = meta.planned_start
    return {
        "webinar_name": meta.webinar_name,
        "date_es": f"{d.day} de {MONTHS_ES[d.month - 1]} de {d.year}" if d is not None else "",
        "date_en": f"{d.day} {MONTHS_EN[d.month - 1]} {d.year}" if d is not None else "",
        "panel": [f"{r.display_name} ({r.role})" for r in staff.itertuples()],
        "panel_names": " ".join(staff.display_name.dropna()),
        "transcript": transcript_text(trimmed),
        "transcript_raw": " ".join(u.text for u in utts),
        "chat": chat_text(chat, staff_names),
        "slides": "\n\n".join(f"[Diapositiva {i + 1}]\n{t}" for i, t in enumerate(slides) if t.strip()),
        "ai_summary": ai_summary,
        "overrides": overrides,
        "series": series or {},
        "event_type": event_type,
    }


def article_lang(path: Path, text: str) -> str:
    """'es' or 'en' for an uploaded article: from the file name (…_es.md, …-en.md), else from the words."""
    m = re.search(r"(?:^|[_\-. ])(es|en|esp|eng|spa)(?:[_\-. ]|$)", path.stem.lower())
    if m:
        return "en" if m.group(1) in ("en", "eng") else "es"
    w = re.findall(r"[a-záéíóúñ]+", text.lower())
    es = sum(x in ("de", "la", "que", "el", "los", "las", "del", "por", "una", "para") for x in w)
    en = sum(x in ("the", "of", "and", "to", "that", "for", "with", "by", "was", "which") for x in w)
    return "es" if es >= en else "en"


def import_article(event_dir: Path, path: Path) -> str:
    """Use an uploaded .md as the event's article; the participation paragraph is added (and kept current)."""
    text = path.read_text(encoding="utf-8-sig").strip() + "\n"
    lang = article_lang(path, text)
    if "<!-- stats:start" not in text:
        block = ("<!-- stats:start (auto-generated from the participation data; edits here are overwritten) -->\n"
                 "…\n<!-- stats:end -->\n")
        nxt = re.search(r"^(La próxima sesión|El próximo evento|The next session|The next event)", text, re.M)
        text = (text[:nxt.start()] + block + "\n" + text[nxt.start():]) if nxt else (text + "\n" + block)
    (event_dir / f"summary_{lang}.md").write_text(text, encoding="utf-8")
    return lang


def write_summaries(event_dir: Path, ctx: dict, stats: dict, force=False) -> dict:
    """Generate (or reuse) summary_es.md / summary_en.md and review.md in event_dir."""
    es_md, en_md = event_dir / "summary_es.md", event_dir / "summary_en.md"
    stats_es, stats_en = stats_paragraph(stats, "es"), stats_paragraph(stats, "en")
    status = {"es": "existing" if es_md.exists() else "missing", "en": "existing" if en_md.exists() else "missing"}
    art_path = event_dir / "article.json"

    arts0 = json.loads(art_path.read_text(encoding="utf-8")) if art_path.exists() else {}
    for lang, md, sp in (("es", es_md, stats_es), ("en", en_md, stats_en)):
        if lang in arts0 and not md.exists():          # article written/edited as JSON by hand
            md.write_text(to_markdown(arts0[lang], sp, lang), encoding="utf-8")
            status[lang] = "from_article_json"

    if force or not es_md.exists():
        client = _client()
        prompt = build_prompt_es(ctx)
        if client is None:
            (event_dir / "prompt_es.md").write_text(SYSTEM_ES + "\n\n" + prompt, encoding="utf-8")
            status["es"] = "prompt_only"
        else:
            art = _ask(client, SYSTEM_ES, prompt)
            art_path.write_text(json.dumps({"es": art}, ensure_ascii=False, indent=1), encoding="utf-8")
            es_md.write_text(to_markdown(art, stats_es, "es"), encoding="utf-8")
            status["es"] = "generated"
    if es_md.exists() and (force or not en_md.exists()):
        client = _client()
        arts = json.loads(art_path.read_text(encoding="utf-8")) if art_path.exists() else {}
        if client is not None and "es" in arts:
            art_en = _ask(client, None, build_prompt_en(arts["es"], stats_en))
            arts["en"] = art_en
            art_path.write_text(json.dumps(arts, ensure_ascii=False, indent=1), encoding="utf-8")
            en_md.write_text(to_markdown(art_en, stats_en, "en"), encoding="utf-8")
            status["en"] = "generated"
        elif not en_md.exists():
            status["en"] = "missing"
    refresh_stats_paragraph(es_md, stats_es)
    refresh_stats_paragraph(en_md, stats_en)
    if es_md.exists():
        arts = json.loads(art_path.read_text(encoding="utf-8")) if art_path.exists() else {}
        (event_dir / "review.md").write_text(
            review(es_md.read_text(encoding="utf-8"), ctx, arts.get("es", {})), encoding="utf-8")
    return status
